//! The elements JMeter offers in its "Add" menus, each with the XML JMeter writes for a new one.
//!
//! The data in `data/templates.txt` is generated by running JMeter itself (see `tools/jmeter-catalog`), so
//! a new element starts with exactly the settings the JMeter GUI would give it.

use crate::catalog::Category;
use anyhow::{Context, Result};
use jmx_model::{Document, Element, Node, Pair};
use std::sync::OnceLock;

const DATA: &str = include_str!("../data/templates.txt");

#[derive(Debug)]
pub struct Template {
    /// JMeter's menu id, for example `menu_timer`.
    pub menu: String,
    pub gui_class: String,
    pub test_class: String,
    /// The name a new element is given, which is also what the menu shows.
    pub label: String,
    /// The XML tag, for example `HTTPSamplerProxy`.
    pub tag: String,
    /// The `guiclass` attribute as saved, for example `HttpTestSampleGui`.
    pub guiclass: String,
    pub category: Category,
    /// Elements described by a property list rather than a hand-built GUI.
    pub testbean: bool,
    xml: String,
}

fn category_of_menu(menu: &str) -> Option<Category> {
    Some(match menu {
        "menu_assertions" => Category::Assertion,
        "menu_config_element" => Category::Config,
        "menu_fragments" => Category::Fragment,
        "menu_generative_controller" => Category::Sampler,
        "menu_listener" => Category::Listener,
        "menu_logic_controller" => Category::Controller,
        "menu_non_test_elements" => Category::NonTest,
        "menu_post_processors" => Category::PostProcessor,
        "menu_pre_processors" => Category::PreProcessor,
        "menu_threads" => Category::ThreadGroup,
        "menu_timer" => Category::Timer,
        _ => return None,
    })
}

/// The element and its (empty) hash tree inside a document `SaveService.saveTree` wrote.
fn first_pair(doc: &Document) -> Result<(&Element, usize)> {
    let tree = doc.root.elements().next().context("no tree in template")?;
    let el = tree.children.iter().position(|n| matches!(n, Node::Element(_))).context("no element in template")?;
    Ok((match &tree.children[el] {
        Node::Element(e) => e,
        _ => unreachable!(),
    }, el))
}

fn parse() -> Vec<Template> {
    let mut out = Vec::new();
    let mut lines = DATA.lines().peekable();
    while let Some(line) = lines.next() {
        let Some(head) = line.strip_prefix("@@@ BEGIN ") else { continue };
        let f: Vec<&str> = head.split(" | ").collect();
        let mut xml = String::new();
        for l in lines.by_ref() {
            if l == "@@@ END" {
                break;
            }
            xml.push_str(l);
            xml.push('\n');
        }
        let [menu, gui_class, test_class, label, testbean] = f[..] else { continue };
        let Some(category) = category_of_menu(menu) else { continue };
        let Ok(doc) = Document::parse(&xml) else { continue };
        let Ok((el, _)) = first_pair(&doc) else { continue };
        out.push(Template {
            menu: menu.to_string(),
            gui_class: gui_class.to_string(),
            test_class: test_class.to_string(),
            label: label.to_string(),
            tag: el.name.clone(),
            guiclass: el.attr("guiclass").unwrap_or_default(),
            category,
            testbean: testbean == "true",
            xml,
        });
    }
    out
}

/// Every template, in the order the generator wrote them.
pub fn all() -> &'static [Template] {
    static ALL: OnceLock<Vec<Template>> = OnceLock::new();
    ALL.get_or_init(parse)
}

/// The template for an element type: its XML tag and `guiclass` attribute.
pub fn find(tag: &str, guiclass: &str) -> Option<&'static Template> {
    all().iter().find(|t| t.tag == tag && t.guiclass == guiclass)
}

impl Template {
    /// A new element of this type, named like its menu entry and enabled.
    pub fn instantiate(&self) -> Pair {
        let doc = Document::parse(&self.xml).expect("templates are checked when loaded");
        let (el, _) = first_pair(&doc).expect("templates are checked when loaded");
        let mut el = el.clone();
        el.set_attr("enabled", "true");
        // The generator's documents write the element at the depth of a plan's first element.
        Pair::with_base(el, Some("    ".to_string()))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_menu_entry_loads() {
        let all = all();
        assert!(all.len() >= 120, "{}", all.len());
        for t in all {
            assert!(!t.tag.is_empty() && !t.guiclass.is_empty() && !t.label.is_empty(), "{t:?}");
            assert!(t.xml.contains("<jmeterTestPlan"));
        }
        assert!(!DATA.contains("@@@ FAILED"), "the generator reported failures");
    }

    #[test]
    fn entries_are_unique_by_tag_and_gui() {
        let mut seen = std::collections::HashSet::new();
        for t in all() {
            assert!(seen.insert((&t.tag, &t.guiclass)), "duplicate {} {}", t.tag, t.guiclass);
        }
    }

    #[test]
    fn menu_groups_match_the_catalog() {
        use crate::catalog::describe;
        for t in all() {
            let (_, cat) = describe(&t.tag, &t.guiclass);
            assert!(cat == t.category || cat == Category::Unknown, "{}: JMeter's menu says {:?}, the catalog says {:?}", t.label, t.category, cat);
        }
    }

    #[test]
    fn http_request_has_what_the_gui_gives_it() {
        let t = find("HTTPSamplerProxy", "HttpTestSampleGui").unwrap();
        assert_eq!(t.label, "HTTP Request");
        assert_eq!(t.category, Category::Sampler);
        let p = t.instantiate();
        assert_eq!(p.element.attr("testname").as_deref(), Some("HTTP Request"));
        assert_eq!(p.element.attr("enabled").as_deref(), Some("true"));
        let names: Vec<_> = p.element.elements().filter_map(|c| c.attr("name")).collect();
        assert!(names.contains(&"HTTPsampler.Arguments".to_string()), "{names:?}");
        assert!(names.contains(&"HTTPSampler.method".to_string()));
    }

    #[test]
    fn listeners_with_the_same_tag_are_told_apart_by_gui() {
        let tree = find("ResultCollector", "ViewResultsFullVisualizer").unwrap();
        let summary = find("ResultCollector", "SummaryReport").unwrap();
        assert_ne!(tree.label, summary.label);
    }
}
